import socket

def scan_ports(host: str, ports: list[int]) -> dict[int, bool]:
    results = {}
    for port in ports:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(1)
        try:
            sock.connect((host, port))
            results[port] = True
        except (socket.timeout, ConnectionRefusedError):
            results[port] = False
        finally:
            sock.close()
    return results
